from typing import Iterable, TypeVar, reveal_type

T = TypeVar('T')

def identity(values: set[T]) -> set[T]:
    return values

def inspect(values: Iterable[int]) -> None:
    reveal_type(identity({x for x in values}))

from typing import Iterable, reveal_type

def inspect(values: Iterable[tuple[int, str]]) -> None:
    item = 'outer'
    result = {item for row in values for item in row}
    reveal_type(result)
    reveal_type(item)
